def _sha(x:Any)->str:return hashlib.sha256(canonical_json(x).encode()).hexdigest()
def _owner_key()->bytes:
    p=os.environ.get('P5_OWNER_ED25519_PUBLIC_KEY_FILE','')
    if not p or not Path(p).is_file():raise FailClosed('OWNER_PUBLIC_KEY_NOT_CONFIGURED')
    b=Path(p).read_bytes()
    if len(b)!=32:raise FailClosed('OWNER_PUBLIC_KEY_INVALID')
    return b
def _owner_uid()->int:return int(os.environ.get('P5_OWNER_PEER_UID','-1'))
AMENDMENT_C_SHA256='5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83'
def _amendment_d_sha256()->str:
 h=os.environ.get('P5_AMENDMENT_D_SHA256','')
 if len(h)!=64 or any(x not in '0123456789abcdef' for x in h):raise FailClosed('AMENDMENT_D_HASH_NOT_PINNED')
 return h
def _expected_amendment_hash(amendment_id:str)->str:
 if amendment_id=='C':return AMENDMENT_C_SHA256
 if amendment_id=='D':return _amendment_d_sha256()
 key='P5_AMENDMENT_'+amendment_id+'_SHA256'
 h=os.environ.get(key,'')
 if len(h)!=64 or any(x not in '0123456789abcdef' for x in h):raise FailClosed(key+'_NOT_PINNED')
 return h

class AuthorityStore:
 def __init__(self,db_path:Path):self.db_path=db_path
 def _open(self):
  c=apsw.Connection(str(self.db_path));c.set_busy_timeout(2000);c.execute('PRAGMA foreign_keys=ON');return c
 def proposal(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  b=FrozenBindings(**payload['bindings']).validate();pid=str(payload['proposal_id']);bj=canonical_json(vars(b));now=ctx.recorded_at
  rph=resource_policy_sha256(b.resource_scope) if b.wave_id is not None else None
  c=self._open()
  try:
   c.execute('BEGIN IMMEDIATE');c.execute('INSERT INTO authority_proposals(proposal_id,family_id,run_id,run_class,binding_sha256,binding_json,producer_session_id,expires_at,created_at,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?)',(pid,b.family_id,b.run_id,b.run_class,b.digest,bj,ctx.session_id,str(payload['expires_at']),now,rph));c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)",(pid,'NONE','PROPOSED',now,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':'PROPOSED','seq':ctx.ledger_sequence}),rph));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','proposal_id':pid,'state':'PROPOSED','binding_sha256':b.digest}
 def transition(self,pid:str,target:str,ctx:DaemonContext,observed_binding_sha256:str|None=None)->dict[str,Any]:
  c=self._open()
  try:
   row=c.execute('SELECT binding_sha256,producer_session_id,expires_at,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?',(pid,)).fetchone()
   if not row:raise FailClosed('PROPOSAL_NOT_FOUND')
   last=c.execute('SELECT transition_id,to_state,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1',(pid,)).fetchone();current=last[1]
   wanted={'PROPOSED':'PRECONDITIONS_PASS','PRECONDITIONS_PASS':'HUMAN_OWNER_SIGNED','HUMAN_OWNER_SIGNED':'APPLIED'}.get(current)
   if target!=wanted:raise FailClosed('ILLEGAL_AUTHORITY_TRANSITION')
   if target=='PRECONDITIONS_PASS' and observed_binding_sha256!=row[0]:raise FailClosed('BINDING_MISMATCH')
   if target in {'HUMAN_OWNER_SIGNED','APPLIED'}:
    if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')
    if ctx.session_id==row[1]:raise FailClosed('OWNER_SESSION_SEPARATION_FAILED')
   c.execute('BEGIN IMMEDIATE');c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)",(pid,current,target,ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':target,'seq':ctx.ledger_sequence}),row[3]));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','proposal_id':pid,'state':target}
 def register_delegation(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  d=OwnerConditionalDelegation(**payload);v=DelegationVerifier(_owner_key());v.verify_signature(d);sig=__import__('base64').b64decode(d.owner_signature)
  rph=resource_policy_sha256(d.resource_policy)
  c=self._open()
  try:
   # Amendment C and D must already have been directly owner-applied before
   # the dormant root credential can enter production.
   observed=list(c.execute('SELECT amendment_id,amendment_sha256 FROM amendment_registrations ORDER BY registration_ordinal'))
   expected=[('C',d.amendment_c_sha256),('D',d.amendment_d_sha256)]
   if observed[:2]!=expected:raise FailClosed('EXACT_C_AND_D_DIRECT_OWNER_APPLIED_REQUIRED')
   c.execute('INSERT INTO owner_conditional_delegations(delegation_id,owner_identity,owner_credential_scheme,unsigned_payload_json,owner_signature_b64,owner_signature_sha256,owner_session_id,expires_at,scope_sha256,state,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(d.delegation_id,d.owner_identity,d.owner_credential_scheme,canonical_json(d.unsigned_payload()),d.owner_signature,hashlib.sha256(sig).hexdigest(),d.owner_session_id,d.expires_at,d.scope_hash,'ACTIVE',rph))
  finally:c.close()
  return {'status':'PASS','delegation_id':d.delegation_id,'scope_sha256':d.scope_hash}
 def redeem(self,delegation_id:str,proposal_payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  c=self._open()
  try:
   r=c.execute('SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?',(delegation_id,)).fetchone()
   if not r:raise FailClosed('DELEGATION_NOT_FOUND')
   dd=json.loads(r[0]);dd['owner_signature']=r[1];d=OwnerConditionalDelegation(**dd);p=ChildProposal(**proposal_payload)
   canonical=c.execute('SELECT producer_session_id,binding_json,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?',(p.proposal_id,)).fetchone()
   if not canonical:raise FailClosed('PROPOSAL_NOT_FOUND')
   # Never trust a child payload's producer-session claim. Bind redemption to
   # the daemon-recorded session that created the canonical proposal.
   p=replace(p,producer_session_id=canonical[0])
   binding=json.loads(canonical[1])
   if p.family!=binding['family_id'] or p.run_class!=binding['run_class'] or p.evidence_domain!=binding['evidence_domain'] or p.evaluator_hash!=binding['evaluator_sha256']:raise FailClosed('CANONICAL_PROPOSAL_SCOPE_MISMATCH')
   if p.proposal_type=='WAVE1_STATISTICAL_TRIAL':
    if p.resource_policy is None or resource_policy_sha256(p.resource_policy)!=canonical[2]:raise FailClosed('RESOURCE_POLICY_BINDING_MISMATCH')
   pre=c.execute("SELECT transition_id,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? AND to_state='PRECONDITIONS_PASS' ORDER BY transition_id DESC LIMIT 1",(p.proposal_id,)).fetchone()
   if not pre:raise FailClosed('PRECONDITIONS_PASS_ABSENT')
   if c.execute('SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?',(delegation_id,)).fetchone():raise FailClosed('DELEGATION_REVOKED')
   event=DelegationVerifier(_owner_key()).redeem(d,p,{'to':'PRECONDITIONS_PASS','ledger_sequence':pre[1],'event_id':str(pre[0])},ctx)
   c.execute('BEGIN IMMEDIATE');c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)",(p.proposal_id,'PRECONDITIONS_PASS','HUMAN_OWNER_SIGNED',ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha(event),event.get('resource_policy_sha256')));tid=c.last_insert_rowid();c.execute('INSERT INTO delegation_redemptions(redemption_event_id,delegation_id,child_proposal_id,preconditions_transition_id,human_owner_signed_transition_id,scope_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?)',(event['redemption_event_id'],delegation_id,p.proposal_id,pre[0],tid,event['scope_hash'],event.get('resource_policy_sha256')));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','event':event}
 def revoke(self,delegation_id:str,ctx:DaemonContext)->dict[str,Any]:
  if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')
  eid='revoke-'+_sha({'d':delegation_id,'seq':ctx.ledger_sequence})[:32];c=self._open()
  try:c.execute('INSERT INTO owner_delegation_revocations VALUES(?,?,?,?,?)',(eid,delegation_id,ctx.recorded_at,ctx.ledger_sequence,ctx.peer_uid))
  finally:c.close()
  return {'status':'PASS','event':'OWNER_DELEGATION_REVOKED','revocation_event_id':eid}
 def register_amendment(self,delegation_id:str,amendment_id:str,amendment_hash:str,ctx:DaemonContext)->dict[str,Any]:
  c=self._open()
  try:
   r=c.execute('SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?',(delegation_id,)).fetchone()
   if not r:raise FailClosed('DELEGATION_NOT_FOUND')
   if c.execute('SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?',(delegation_id,)).fetchone():raise FailClosed('DELEGATION_REVOKED')
   dd=json.loads(r[0]);dd['owner_signature']=r[1];d=OwnerConditionalDelegation(**dd);v=DelegationVerifier(_owner_key());v.verify_signature(d)
   observed=[x[0] for x in c.execute('SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal')]
   if observed[:2]!=['C','D'] or amendment_id not in {'A','B'}:raise FailClosed('C_D_A_B_ORDER_VIOLATION')
   expected=['C','D','A','B']
   if observed!=expected[:len(observed)] or len(observed)>=4 or amendment_id!=expected[len(observed)]:raise FailClosed('C_D_A_B_ORDER_VIOLATION')
   exact={'A':d.amendment_a_sha256,'B':d.amendment_b_sha256}
   if amendment_hash!=exact[amendment_id]:raise FailClosed('AMENDMENT_ID_HASH_BINDING_MISMATCH')
   eid='amend-'+_sha({'d':delegation_id,'a':amendment_id,'seq':ctx.ledger_sequence})[:32]
   c.execute('INSERT INTO amendment_registrations VALUES(?,?,?,?,?,?,?)',(eid,amendment_id,amendment_hash,len(observed)+1,'PREAUTHORIZED_CONDITIONAL_DELEGATION',delegation_id,ctx.recorded_at))
  finally:c.close()
  return {'status':'PASS','amendment_event_id':eid,'amendment_id':amendment_id,'registration_ordinal':len(observed)+1}

 def register_amendment_direct(self,amendment_id:str,amendment_hash:str,producer_session_id:str,ctx:DaemonContext)->dict[str,Any]:
  if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')
  if not producer_session_id or producer_session_id==ctx.session_id:raise FailClosed('OWNER_SESSION_SEPARATION_FAILED')
  if amendment_id not in {'C','D'}:raise FailClosed('DIRECT_OWNER_ONLY_C_OR_D')
  if amendment_hash!=_expected_amendment_hash(amendment_id):raise FailClosed('AMENDMENT_ID_HASH_BINDING_MISMATCH')
  c=self._open()
  try:
   observed=[x[0] for x in c.execute('SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal')]
   expected=['C','D']
   if observed!=expected[:len(observed)] or len(observed)>=2 or amendment_id!=expected[len(observed)]:raise FailClosed('C_FIRST_D_SECOND_REQUIRED')
   eid='amend-direct-'+_sha({'a':amendment_id,'h':amendment_hash,'seq':ctx.ledger_sequence})[:32]
   c.execute('INSERT INTO amendment_registrations(amendment_event_id,amendment_id,amendment_sha256,registration_ordinal,authorization_mode,delegation_id,daemon_recorded_at,producer_session_id,owner_session_id) VALUES(?,?,?,?,?,?,?,?,?)',(eid,amendment_id,amendment_hash,len(observed)+1,'INTERACTIVE_OWNER_SIGN',None,ctx.recorded_at,producer_session_id,ctx.session_id))
  finally:c.close()
  return {'status':'PASS','amendment_event_id':eid,'amendment_id':amendment_id,'registration_ordinal':len(observed)+1}

"""P5 PC7 authority/amendment/trial runtime (engineering layer).

The daemon supplies ``peer_uid``, append-only sequence and canonical time.
Producer timestamps and payload role strings are never authorization inputs.
This module has no Research Memory write path; production persistence is the
separate, audited schema migration.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
import hashlib
import json
from typing import Any, Callable


STATES = ("PROPOSED", "PRECONDITIONS_PASS", "HUMAN_OWNER_SIGNED", "APPLIED")
RUN_CLASSES = {"STATISTICAL_TRIAL", "SYNTHETIC_TEST"}

RESOURCE_POLICY_TYPE = "WAVE1_CUMULATIVE_ACTIVE_WALL_TIME_V1"
RESOURCE_POLICY_KEYS = {
    "policy_type", "wall_time_expiry_seconds", "clock", "starts_at",
    "accumulation", "checkpoint_semantics", "on_exhaustion",
    "scientific_early_stop", "candidate_count", "decision_basis",
}
RESOURCE_DECISION_BASIS_KEYS = {
    "source", "benchmark_sha256", "real_p5_labels_read_before_choice",
}


class AuthorityError(RuntimeError):
    pass


class AuthorizationDenied(AuthorityError):
    pass


class BindingMismatch(AuthorityError):
    pass


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def parse_utc(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise AuthorityError("daemon time must be RFC3339 UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AuthorityError("daemon time must be UTC")
    return parsed


def validate_resource_policy(value: Any) -> dict[str, Any]:
    """Validate the owner-late-bound, outcome-blind Wave-1 resource policy.

    Amendment D defines ``wall_time_expiry`` as a cumulative active-attempt
    duration in integer seconds.  It is deliberately distinct from the
    security credential's absolute ``expires_at`` timestamp.  The owner
    chooses the integer after the sealed synthetic benchmark and before the
    first P3 real-label access; this function never supplies a default.
    """
    if not isinstance(value, dict) or set(value) != RESOURCE_POLICY_KEYS:
        raise AuthorityError("RESOURCE_POLICY_EXACT_FIELDS_REQUIRED")
    if value["policy_type"] != RESOURCE_POLICY_TYPE:
        raise AuthorityError("RESOURCE_POLICY_TYPE_INVALID")
    seconds = value["wall_time_expiry_seconds"]
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds <= 0:
        raise AuthorityError("RESOURCE_POLICY_SECONDS_INVALID")
    expected = {
        "clock": "DAEMON_MONOTONIC_ACTIVE_ATTEMPT_TIME",
        "starts_at": "WAVE1_APPLIED",
        "accumulation": "SUM_ALL_ATTEMPTS_SAME_LOGICAL_WAVE",
        "checkpoint_semantics": "SEALED_PARTIAL_CHECKPOINT_RESUME_ONLY",
        "on_exhaustion": "RESOURCE_EXHAUSTED_OWNER_ACTION_REQUIRED",
        "scientific_early_stop": False,
        "candidate_count": 174,
    }
    if any(value.get(key) != wanted for key, wanted in expected.items()):
        raise AuthorityError("RESOURCE_POLICY_SEMANTICS_INVALID")
    basis = value.get("decision_basis")
    if not isinstance(basis, dict) or set(basis) != RESOURCE_DECISION_BASIS_KEYS:
        raise AuthorityError("RESOURCE_POLICY_DECISION_BASIS_INVALID")
    if basis.get("source") != "SEALED_SYNTHETIC_FULL_PATH_BENCHMARK_ONLY":
        raise AuthorityError("RESOURCE_POLICY_OUTCOME_DERIVED")
    if basis.get("real_p5_labels_read_before_choice") is not False:
        raise AuthorityError("RESOURCE_POLICY_OUTCOME_DERIVED")
    digest = basis.get("benchmark_sha256")
    if not isinstance(digest, str) or len(digest) != 64 or any(
            c not in "0123456789abcdef" for c in digest):
        raise AuthorityError("RESOURCE_POLICY_BENCHMARK_HASH_INVALID")
    return value


def resource_policy_sha256(value: Any) -> str:
    validate_resource_policy(value)
    return sha256(canonical_json(value))


